func functions(name string)map[string]string {set:=token.NewFileSet();f,e:=parser.ParseFile(set,name,nil,0);if e!=nil{panic(e)};r:=map[string]string{};for _,d:=range f.Decls{fn,ok:=d.(*ast.FuncDecl);if !ok{continue};k:=fn.Name.Name;if fn.Recv!=nil{var b bytes.Buffer;format.Node(&b,set,fn.Recv.List[0].Type);k=b.String()+"."+k};var b bytes.Buffer;format.Node(&b,set,fn);r[k]=b.String()};return r}
